import{_ as o}from"./chunks/cngal-background-logo.CTvRSuWB.js";import{_ as a,a as e}from"./chunks/tripo-light.BNMcUtVL.js";import{_ as r,o as i,c as s,a5 as n}from"./chunks/framework.BEZBAInb.js";const q=JSON.parse('{"title":"关于 Konado","description":"","frontmatter":{"title":"关于 Konado","order":1},"headers":[],"relativePath":"zh/2.4/introduction/konado.md","filePath":"zh/2.4/introduction/konado.md","lastUpdated":1788455378000}'),d={name:"zh/2.4/introduction/konado.md"},h=e,l=a;function c(p,t,m,u,g,b){return i(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="关于-konado" tabindex="-1">关于 Konado <a class="header-anchor" href="#关于-konado" aria-label="Permalink to &quot;关于 Konado&quot;">​</a></h1><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p>Konado 是一款基于 Godot Engine 的视觉小说引擎框架，由开源社区驱动。我们致力于为开发者提供高效、便捷的视觉小说开发体验，帮助创作者快速构建高质量的视觉小说作品，为创作赋能。我们追求更友好、更高效的工具，让游戏创作者能够专注于故事叙述与艺术表现，而不必陷入程序实现的细节之中。</p><h2 id="项目荣誉" tabindex="-1">项目荣誉 <a class="header-anchor" href="#项目荣誉" aria-label="Permalink to &quot;项目荣誉&quot;">​</a></h2><ul><li>Konado 已被收录至 Godot Engine 官方 <a href="https://github.com/godotengine/awesome-godot" target="_blank" rel="noreferrer">awesome-godot</a> 项目的“Plugins and scripts”部分，作为推荐的插件之一。</li><li>Konado 荣幸获得 <a href="https://atomgit.com/GitCode/G-Star100" target="_blank" rel="noreferrer">2025 AtomGit 百大开源项目</a> 荣誉，并被收录于 <a href="https://gstar-landscape.gitcode.com/?item=%E9%9F%B3%E8%A7%86%E9%A2%91-%E5%9B%BE%E5%BD%A2-%E6%B8%B8%E6%88%8F-3d--%E6%B8%B8%E6%88%8F%E5%BC%95%E6%93%8E-unity-unreal-godot--konado" target="_blank" rel="noreferrer">AtomGit G-Star Landscape 3.0</a> 生态全景图中。</li></ul><h2 id="项目贡献者" tabindex="-1">项目贡献者 <a class="header-anchor" href="#项目贡献者" aria-label="Permalink to &quot;项目贡献者&quot;">​</a></h2><p>以下贡献者图表由 <a href="https://contrib.rocks" target="_blank" rel="noreferrer">contrib.rocks</a> 生成，会实时更新项目贡献者信息。</p><picture><source media="(prefers-color-scheme: dark)" srcset="https://contrib.rocks/image?repo=godothub/konado&amp;theme=dark"><source media="(prefers-color-scheme: light)" srcset="https://contrib.rocks/image?repo=godothub/konado"><img alt="Contributors" src="https://contrib.rocks/image?repo=godothub/konado"></picture><h2 id="github-star-history" tabindex="-1">GitHub Star History <a class="header-anchor" href="#github-star-history" aria-label="Permalink to &quot;GitHub Star History&quot;">​</a></h2><picture><source media="(prefers-color-scheme: dark)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;theme=dark&amp;legend=top-left"><source media="(prefers-color-scheme: light)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"><img alt="Star History Chart" src="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"></picture><h2 id="atomgit-star-history" tabindex="-1">AtomGit Star History <a class="header-anchor" href="#atomgit-star-history" aria-label="Permalink to &quot;AtomGit Star History&quot;">​</a></h2><p><img src="https://atomgit.com/godothub/konado/starcharts.svg?variant=adaptive" alt="AtomGit Star History"></p><h2 id="赞助我们" tabindex="-1">赞助我们 <a class="header-anchor" href="#赞助我们" aria-label="Permalink to &quot;赞助我们&quot;">​</a></h2><p>如果您喜欢 Konado 项目，并希望支持我们的工作，欢迎通过以下方式赞助我们：</p><ul><li><a href="https://afdian.com/item/52230b2860a011f083ef52540025c377" target="_blank" rel="noreferrer">爱发电</a></li></ul><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>如果您对 Konado 项目感兴趣，欢迎加入我们的 QQ 频道交流群，共同探讨 Konado 的未来发展方向：</p><ul><li>QQ 频道交流群：<a href="https://pd.qq.com/g/godot" target="_blank" rel="noreferrer">https://pd.qq.com/g/godot</a></li></ul><p>如有问题反馈或功能建议，欢迎前往 Konado 的项目<a href="https://github.com/godothub/konado/issues" target="_blank" rel="noreferrer">仓库提交 Issue</a>。</p><p>如有其他问题，请发送邮件至：<a href="mailto:konado@godothub.com" target="_blank" rel="noreferrer">konado@godothub.com</a></p><h2 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h2><div style="text-align:center;"><a href="https://www.cngal.org" target="_blank" rel="noopener noreferrer"><img src="'+o+'" alt="CNGAL" style="max-width:320px;width:70%;height:auto;"></a></div><p>感谢Tripo对Konado视觉小说创意周的支持</p><div style="text-align:center;"><a href="https://www.tripo3d.ai/zh" target="_blank" rel="noopener noreferrer"><picture><source media="(prefers-color-scheme: dark)" srcset="'+h+'"><source media="(prefers-color-scheme: light)" srcset="'+l+'"><img alt="Tripo" src="'+a+'" style="max-width:320px;width:70%;height:auto;"></picture></a></div>',24)])])}const y=r(d,[["render",c]]);export{q as __pageData,y as default};
